const q = $json.query || {};
if (q.skip) return [{ json: { html: '<h2>Skipped ✔</h2>' } }];
const msg = `Namaste! Please arrange: ${q.item} — qty ${q.qty||5}. Confirm price and delivery date. — ${$env.BRAND_NAME||'PSG Gold'}`;
const wa = 'https://wa.me/' + String(q.sup||'').replace(/\D/g,'') + '?text=' + encodeURIComponent(msg);
return [{ json: { html: `<h2>PO drafted ✔</h2><p><a style="font-size:22px" href="${wa}">👉 Tap to send to supplier on WhatsApp</a></p><p>${msg}</p>` } }];

const r = items.at(-1)?.json || {};
const rate = Number(r.Rate24K||0);
const hi = Number($env.RATE_ALERT_ABOVE||999999), lo = Number($env.RATE_ALERT_BELOW||0);
if (rate >= hi) return [{ json: { text: `📈 Gold 24K crossed ₹${hi}: now ₹${rate}/g. Consider messaging fence-sitters ('rates rising — book now') & review stock pricing.` } }];
if (rate && rate <= lo) return [{ json: { text: `📉 Gold 24K dipped below ₹${lo}: now ₹${rate}/g. Good buying window — alert scheme members & bargain hunters.` } }];
return [];
